item.content:encoded:





          &lt;p&gt;&lt;strong&gt;Open WebUI v0.12.4 में सुरक्षा सुधार हैं, जिनकी रखरखावकर्ताओं ने अभी पूरी सूची नहीं दी है।&lt;/strong&gt; रिलीज़ नोट जल्द अपडेट करने की सलाह देते हैं और कहते हैं कि CVE मिलने के बाद सलाह जारी की जाएगी। नीचे नामित चैट-साझाकरण और अनुमति बदलाव रिलीज़ नोट में दिखने वाले बिंदु हैं। ये अप्रकाशित सुरक्षा सुधारों की पूरी सूची नहीं हैं। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;Open WebUI v0.12.4 रिलीज़ नोट&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://github.com/open-webui/open-webui/releases/tag/v0.12.4&#34;&gt;
    &lt;a href=&#34;https://github.com/open-webui/open-webui/releases/tag/v0.12.4&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;Open WebUI v0.12.4 रिलीज़ नोट&lt;/a&gt;
&lt;/span&gt;
&lt;/p&gt;
&lt;h2 id=&#34;मखय-बत&#34;&gt;
  &lt;a href=&#34;#%e0%a4%ae%e0%a4%96%e0%a4%af-%e0%a4%ac%e0%a4%a4&#34; title=&#34;मुख्य बातें&#34;&gt;मुख्य बातें&lt;/a&gt;
  &lt;a href=&#34;#%e0%a4%ae%e0%a4%96%e0%a4%af-%e0%a4%ac%e0%a4%a4&#34; class=&#34;h-anchor&#34; aria-hidden=&#34;true&#34; title=&#34;मुख्य बातें&#34;&gt;#&lt;/a&gt;
&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;पहले बैकअप लें।&lt;/strong&gt; ऐप बदलने से पहले डेटा वॉल्यूम या डेटाबेस और अपलोड की पुनर्स्थापित की जा सकने वाली प्रति रखें।&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;आधिकारिक रिलीज़ पिन करें।&lt;/strong&gt; मानक Docker इमेज के लिए &lt;code&gt;ghcr.io/open-webui/open-webui:v0.12.4&lt;/code&gt; और pip के लिए &lt;code&gt;open-webui==0.12.4&lt;/code&gt; उपयोग करें।&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;वास्तविक उपयोगकर्ता भूमिकाओं से अनुमतियाँ जाँचें।&lt;/strong&gt; बटन छिपना API में अनुमति-जाँच का प्रमाण नहीं है।&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;पहुँच निजी रखें।&lt;/strong&gt; ऐप प्रमाणीकरण आवश्यक करें और VPN या प्रमाणीकृत रिवर्स प्रॉक्सी से नेटवर्क पहुँच सीमित करें।&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;अपगरड-स-पहल&#34;&gt;
  &lt;a href=&#34;#%e0%a4%85%e0%a4%aa%e0%a4%97%e0%a4%b0%e0%a4%a1-%e0%a4%b8-%e0%a4%aa%e0%a4%b9%e0%a4%b2&#34; title=&#34;अपग्रेड से पहले&#34;&gt;अपग्रेड से पहले&lt;/a&gt;
  &lt;a href=&#34;#%e0%a4%85%e0%a4%aa%e0%a4%97%e0%a4%b0%e0%a4%a1-%e0%a4%b8-%e0%a4%aa%e0%a4%b9%e0%a4%b2&#34; class=&#34;h-anchor&#34; aria-hidden=&#34;true&#34; title=&#34;अपग्रेड से पहले&#34;&gt;#&lt;/a&gt;
&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;पूर्वापेक्षाएँ:&lt;/strong&gt; मौजूदा इंस्टॉल विधि, कंटेनर इमेज का प्रकार, स्थायी डेटा का स्थान, बाहरी डेटाबेस, रिवर्स प्रॉक्सी और प्रमाणीकरण प्रदाता पहचानें। सेवा-विराम का समय तय करें और मौजूदा कंटेनर कॉन्फ़िगरेशन या सेवा परिभाषा सुरक्षित रखें। अलग इंस्टेंस पर रीस्टोर का अभ्यास करने के लिए समय रखें। नीचे दिए गए कमांड प्रदाता के दस्तावेज़ित तरीकों के उदाहरण हैं, जिन्हें इस तय संस्करण के अनुरूप बदला गया है। ये इस गाइड के लिए किए गए वास्तविक अपग्रेड के परिणाम नहीं हैं। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;Open WebUI अपडेट करना&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/updating/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/updating/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;Open WebUI अपडेट करना&lt;/a&gt;
&lt;/span&gt;
&lt;/p&gt;
&lt;ol&gt;
&lt;li&gt;&lt;strong&gt;स्टोरेज की सूची बनाएँ।&lt;/strong&gt; मानक Docker सेटअप में &lt;code&gt;open-webui&lt;/code&gt;, &lt;code&gt;/app/backend/data&lt;/code&gt; पर माउंट होता है। बाइंड माउंट, बाहरी डेटाबेस, ऑब्जेक्ट स्टोरेज और कस्टम पर्यावरण चर दर्ज करें। pip के लिए, वातावरण बदलने से पहले सक्रिय ऐप डेटा डायरेक्टरी और डेटाबेस ढूँढें। चैट एक्सपोर्ट को पूरा बैकअप न मानें।&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;लिखना रोककर बैकअप लें।&lt;/strong&gt; ऐप रोकें या डेटाबेस का सुसंगत स्नैपशॉट लें। फिर वॉल्यूम, कोई भी बाहरी डेटाबेस और अपलोड अलग स्टोरेज में कॉपी करें। प्रदाता Docker वॉल्यूम आर्काइव करने का तरीका बताता है। वॉल्यूम नाम और बैकअप पथ अपने डिप्लॉयमेंट के अनुसार बदलें। आर्काइव खुलता है या नहीं, जाँचें और भरोसा करने से पहले अलग इंस्टेंस पर रीस्टोर का अभ्यास करें। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;बैकअप और रीस्टोर&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/updating/#backup--restore&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/updating/#backup--restore&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;बैकअप और रीस्टोर&lt;/a&gt;
&lt;/span&gt;
&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;रिलीज़ नोट और माइग्रेशन मार्गदर्शन पढ़ें।&lt;/strong&gt; v0.12.4 के नोट लंबित सुरक्षा सुधारों की सूची या प्रभावित संस्करणों की सीमा नहीं बताते। इन सुधारों को CVE न दें और यह न मानें कि v0.12.4 से पहले हर संस्करण किसी एक दोष से प्रभावित है। अपडेट गाइड एकतरफ़ा डेटाबेस माइग्रेशन और अलग-अलग संस्करणों वाले रेप्लिका के जोखिम बताती है। यदि कई वर्कर या रेप्लिका एक डेटाबेस साझा करते हैं, तो उन्हें साथ रोकें और 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;एकाधिक रेप्लिका माइग्रेशन प्रक्रिया&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/troubleshooting/multi-replica/#updates-and-migrations&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/troubleshooting/multi-replica/#updates-and-migrations&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;एकाधिक रेप्लिका माइग्रेशन प्रक्रिया&lt;/a&gt;
&lt;/span&gt;
 अपनाएँ। रोलबैक के लिए अपग्रेड से पहले का डेटाबेस बैकअप चाहिए हो सकता है।&lt;/li&gt;
&lt;/ol&gt;
&lt;h2 id=&#34;इसटल-कए-गए-पकज-क-अपडट-कर&#34;&gt;
  &lt;a href=&#34;#%e0%a4%87%e0%a4%b8%e0%a4%9f%e0%a4%b2-%e0%a4%95%e0%a4%8f-%e0%a4%97%e0%a4%8f-%e0%a4%aa%e0%a4%95%e0%a4%9c-%e0%a4%95-%e0%a4%85%e0%a4%aa%e0%a4%a1%e0%a4%9f-%e0%a4%95%e0%a4%b0&#34; title=&#34;इंस्टॉल किए गए पैकेज को अपडेट करें&#34;&gt;इंस्टॉल किए गए पैकेज को अपडेट करें&lt;/a&gt;
  &lt;a href=&#34;#%e0%a4%87%e0%a4%b8%e0%a4%9f%e0%a4%b2-%e0%a4%95%e0%a4%8f-%e0%a4%97%e0%a4%8f-%e0%a4%aa%e0%a4%95%e0%a4%9c-%e0%a4%95-%e0%a4%85%e0%a4%aa%e0%a4%a1%e0%a4%9f-%e0%a4%95%e0%a4%b0&#34; class=&#34;h-anchor&#34; aria-hidden=&#34;true&#34; title=&#34;इंस्टॉल किए गए पैकेज को अपडेट करें&#34;&gt;#&lt;/a&gt;
&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;Docker, पिन किए गए टैग के लिए अनुकूलित प्रदाता प्रक्रिया:&lt;/strong&gt; बैकअप के बाद आधिकारिक मानक इमेज खींचें और उसी स्थायी वॉल्यूम, कॉन्फ़िगरेशन तथा &lt;code&gt;WEBUI_SECRET_KEY&lt;/code&gt; के साथ कंटेनर फिर बनाएँ। उदाहरण डिफ़ॉल्ट नाम वाले वॉल्यूम और उसी मशीन पर बँधे प्रॉक्सी अपस्ट्रीम को मानता है। असली कुंजी शेल इतिहास में न डालें। इसे अपने मौजूदा सुरक्षित वातावरण या सीक्रेट प्रबंधन तंत्र से दें। वर्तमान डिप्लॉयमेंट के GPU, Ollama, कस्टम नेटवर्क, डेटाबेस और अन्य विकल्प बनाए रखें। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;Open WebUI अपडेट करना&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/updating/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/updating/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;Open WebUI अपडेट करना&lt;/a&gt;
&lt;/span&gt;
 · 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;आधिकारिक इमेज टैग&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/quick-start/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/quick-start/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;आधिकारिक इमेज टैग&lt;/a&gt;
&lt;/span&gt;
&lt;/p&gt;
&lt;div class=&#34;highlight&#34;&gt;&lt;pre tabindex=&#34;0&#34; style=&#34;color:#f8f8f2;background-color:#272822;-moz-tab-size:4;-o-tab-size:4;tab-size:4;-webkit-text-size-adjust:none;&#34;&gt;&lt;code class=&#34;language-bash&#34; data-lang=&#34;bash&#34;&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;docker pull ghcr.io/open-webui/open-webui:v0.12.4
&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;docker rm -f open-webui
&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;docker run -d --name open-webui --restart always &lt;span style=&#34;color:#ae81ff&#34;&gt;\
&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;  -p 127.0.0.1:3000:8080 &lt;span style=&#34;color:#ae81ff&#34;&gt;\
&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;  -v open-webui:/app/backend/data &lt;span style=&#34;color:#ae81ff&#34;&gt;\
&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;  --env-file ./open-webui.env &lt;span style=&#34;color:#ae81ff&#34;&gt;\
&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;  ghcr.io/open-webui/open-webui:v0.12.4
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;चलाने से पहले &lt;code&gt;./open-webui.env&lt;/code&gt; जाँचें:&lt;/strong&gt; फ़ाइल पहले से मौजूद हो, उसके अनुमतियाँ सीमित हों, और उसमें मौजूदा &lt;code&gt;WEBUI_SECRET_KEY&lt;/code&gt; व ज़रूरी कॉन्फ़िगरेशन हो। लूपबैक बाइंडिंग उसी होस्ट के प्रॉक्सी के लिए है, दूसरी मशीन के प्रॉक्सी के लिए नहीं। Compose में केवल सेवा इमेज को पिन किए टैग पर बदलें, फिर मौजूदा प्रोजेक्ट में &lt;code&gt;docker compose pull open-webui&lt;/code&gt; और &lt;code&gt;docker compose up -d open-webui&lt;/code&gt; चलाएँ। वही वॉल्यूम और पर्यावरण कॉन्फ़िगरेशन रखें। ये सुझाए गए कमांड हैं, आपके डिप्लॉयमेंट का परखा हुआ माइग्रेशन नहीं।&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;pip, निश्चित संस्करण वाला प्रदाता अपडेट तरीका:&lt;/strong&gt; मौजूदा वर्चुअल वातावरण में सेवा रोकें, पैकेज का ठीक संस्करण इंस्टॉल करें और उसी डेटा डायरेक्टरी व वातावरण के साथ फिर शुरू करें। दूसरा Python वातावरण या नया खाली डेटाबेस न बनाएँ। प्रदाता का सामान्य अपडेट निर्देश &lt;code&gt;pip install -U open-webui&lt;/code&gt; है। नीचे की संस्करण सीमा इस चेकलिस्ट को v0.12.4 पर पिन करती है। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;Open WebUI अपडेट करना&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/updating/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/updating/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;Open WebUI अपडेट करना&lt;/a&gt;
&lt;/span&gt;
 · 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;त्वरित शुरुआत&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/quick-start/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/quick-start/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;त्वरित शुरुआत&lt;/a&gt;
&lt;/span&gt;
&lt;/p&gt;
&lt;div class=&#34;highlight&#34;&gt;&lt;pre tabindex=&#34;0&#34; style=&#34;color:#f8f8f2;background-color:#272822;-moz-tab-size:4;-o-tab-size:4;tab-size:4;-webkit-text-size-adjust:none;&#34;&gt;&lt;code class=&#34;language-bash&#34; data-lang=&#34;bash&#34;&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;python -m pip install --upgrade &lt;span style=&#34;color:#e6db74&#34;&gt;&#39;open-webui==0.12.4&#39;&lt;/span&gt;
&lt;/span&gt;&lt;/span&gt;&lt;span style=&#34;display:flex;&#34;&gt;&lt;span&gt;python -m pip show open-webui
&lt;/span&gt;&lt;/span&gt;&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;चलती सेवा जाँचें, केवल इंस्टॉल किए पैकेज को नहीं।&lt;/strong&gt; &lt;code&gt;docker logs open-webui&lt;/code&gt; या pip सेवा लॉग में स्टार्टअप संस्करण देखें और लॉगिन के बाद ऐप में दिख रहे संस्करण से तुलना करें। प्रदाता अपडेट गाइड कंटेनर लॉग जाँचने और लॉगिन पृष्ठ खोलने की सलाह देती है। UI पुरानी सामग्री दिखाए तो ब्राउज़र को ज़बरन रिफ़्रेश करें। स्टार्टअप में माइग्रेशन त्रुटि आए तो कारण पता चलने तक सेवा बंद रखें। रीस्टोर आवश्यकताएँ जाँचे बिना माइग्रेटेड डेटाबेस पर पुराना बाइनरी न चलाएँ। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;अपडेट के बाद की जाँच&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/updating/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/updating/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;अपडेट के बाद की जाँच&lt;/a&gt;
&lt;/span&gt;
&lt;/p&gt;
&lt;h2 id=&#34;रसटरट-क-बद-पहच-जच&#34;&gt;
  &lt;a href=&#34;#%e0%a4%b0%e0%a4%b8%e0%a4%9f%e0%a4%b0%e0%a4%9f-%e0%a4%95-%e0%a4%ac%e0%a4%a6-%e0%a4%aa%e0%a4%b9%e0%a4%9a-%e0%a4%9c%e0%a4%9a&#34; title=&#34;रीस्टार्ट के बाद पहुँच जाँचें&#34;&gt;रीस्टार्ट के बाद पहुँच जाँचें&lt;/a&gt;
  &lt;a href=&#34;#%e0%a4%b0%e0%a4%b8%e0%a4%9f%e0%a4%b0%e0%a4%9f-%e0%a4%95-%e0%a4%ac%e0%a4%a6-%e0%a4%aa%e0%a4%b9%e0%a4%9a-%e0%a4%9c%e0%a4%9a&#34; class=&#34;h-anchor&#34; aria-hidden=&#34;true&#34; title=&#34;रीस्टार्ट के बाद पहुँच जाँचें&#34;&gt;#&lt;/a&gt;
&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;प्रदाता द्वारा बताया गया व्यवहार:&lt;/strong&gt; v0.12.4 उन उपयोगकर्ताओं से फ़ोल्डर एक्सपोर्ट, संग्रहीत चैट एक्सपोर्ट और चैट कॉपी छिपाता है जिनके पास &lt;strong&gt;Allow Chat Export&lt;/strong&gt; नहीं है। जिन उपयोगकर्ताओं के पास संबंधित साझा अनुमति नहीं है, उनसे मॉडल, प्रॉम्प्ट, टूल, ज्ञान, कौशल, नोट्स और फ़ोल्डर के एक्सेस नियंत्रण भी छिपते हैं। साझा फ़ोल्डर देखने वालों को मालिक द्वारा चैट संग्रहित करने के बाद लाइव अपडेट नहीं मिलते। साझा लिंक देखने वालों को मालिक द्वारा सभी चैट का साझा हटाने के बाद लाइव अपडेट नहीं मिलते। नियंत्रण छिपना UI का व्यवहार है, किसी अज्ञात दोष के सर्वर-पक्षीय सुधार का प्रमाण नहीं। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;रिलीज़ नोट&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://github.com/open-webui/open-webui/releases/tag/v0.12.4&#34;&gt;
    &lt;a href=&#34;https://github.com/open-webui/open-webui/releases/tag/v0.12.4&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;रिलीज़ नोट&lt;/a&gt;
&lt;/span&gt;
&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;ऑपरेटर के लिए सुझाई गई जाँच:&lt;/strong&gt; निर्यात और साझा अनुमतियों के बिना परीक्षण खाते से देखें कि नामित कार्रवाइयाँ अनुपस्थित हैं। अनुमति वाले खाते से पुष्टि करें कि अपेक्षित कार्रवाइयाँ चलती हैं। साझा फ़ोल्डर में गैर-संवेदनशील परीक्षण चैट बनाएँ, दूसरे खाते से देखें, मालिक के रूप में संग्रहित करें और पुष्टि करें कि दर्शक को नए अपडेट मिलना बंद हो जाते हैं। साझा लिंक और &lt;strong&gt;Unshare All Chats&lt;/strong&gt; के साथ भी दोहराएँ। सहेजी गई अनुमति और पुराने लिंक फिर जाँचें। संग्रहित सामग्री या पुराने कॉपी हट चुके हैं, ऐसा न मानें।&lt;/p&gt;
&lt;table&gt;
	&lt;thead&gt;
			&lt;tr&gt;
					&lt;th&gt;समीक्षा क्षेत्र&lt;/th&gt;
					&lt;th&gt;क्या जाँचना है&lt;/th&gt;
			&lt;/tr&gt;
	&lt;/thead&gt;
	&lt;tbody&gt;
			&lt;tr&gt;
					&lt;td&gt;&lt;strong&gt;भूमिकाएँ और समूह&lt;/strong&gt;&lt;/td&gt;
					&lt;td&gt;पुराने सदस्यों और व्यवस्थापक आवंटन हटाएँ। नए स्वीकृत उपयोगकर्ता और प्रतिबंधित उपयोगकर्ता की प्रभावी अनुमतियाँ जाँचें।&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
					&lt;td&gt;&lt;strong&gt;मॉडल और टूल&lt;/strong&gt;&lt;/td&gt;
					&lt;td&gt;हर मॉडल की पहुँच अनुमति, जुड़े टूल, टूल बनाने के अधिकार और प्रदाता क्रेडेंशियल देखें। गैर-व्यवस्थापक खाते से परीक्षण करें।&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
					&lt;td&gt;&lt;strong&gt;ज्ञान और फ़ाइलें&lt;/strong&gt;&lt;/td&gt;
					&lt;td&gt;नॉलेज बेस सहयोगियों, संसाधन अनुमतियों, अटैचमेंट और साझा सेटिंग की जाँच करें। उस खाते को भी जाँचें जिसकी पहुँच हटाई गई है।&lt;/td&gt;
			&lt;/tr&gt;
			&lt;tr&gt;
					&lt;td&gt;&lt;strong&gt;चैट और एक्सपोर्ट&lt;/strong&gt;&lt;/td&gt;
					&lt;td&gt;साझा फ़ोल्डर, साझा लिंक, संग्रहीत चैट और Allow Chat Export आवंटन देखें। अनावश्यक लिंक रद्द करें।&lt;/td&gt;
			&lt;/tr&gt;
	&lt;/tbody&gt;
&lt;/table&gt;
&lt;p&gt;ये सूची-जाँच &lt;strong&gt;ऑपरेटर की सिफारिशें&lt;/strong&gt; हैं, v0.12.4 की नई गारंटी नहीं। प्रदाता की 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;हार्डनिंग गाइड&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/advanced-topics/hardening/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/advanced-topics/hardening/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;हार्डनिंग गाइड&lt;/a&gt;
&lt;/span&gt;
 परतदार भूमिकाएँ, समूह, प्रति-संसाधन अनुमतियाँ, कार्यक्षेत्र अनुमतियाँ, API कुंजियाँ और नेटवर्क पर स्थान बताती है।&lt;/p&gt;
&lt;h2 id=&#34;खत-और-नटवरक-क-कमय-दर-कर&#34;&gt;
  &lt;a href=&#34;#%e0%a4%96%e0%a4%a4-%e0%a4%94%e0%a4%b0-%e0%a4%a8%e0%a4%9f%e0%a4%b5%e0%a4%b0%e0%a4%95-%e0%a4%95-%e0%a4%95%e0%a4%ae%e0%a4%af-%e0%a4%a6%e0%a4%b0-%e0%a4%95%e0%a4%b0&#34; title=&#34;खाते और नेटवर्क की कमियाँ दूर करें&#34;&gt;खाते और नेटवर्क की कमियाँ दूर करें&lt;/a&gt;
  &lt;a href=&#34;#%e0%a4%96%e0%a4%a4-%e0%a4%94%e0%a4%b0-%e0%a4%a8%e0%a4%9f%e0%a4%b5%e0%a4%b0%e0%a4%95-%e0%a4%95-%e0%a4%95%e0%a4%ae%e0%a4%af-%e0%a4%a6%e0%a4%b0-%e0%a4%95%e0%a4%b0&#34; class=&#34;h-anchor&#34; aria-hidden=&#34;true&#34; title=&#34;खाते और नेटवर्क की कमियाँ दूर करें&#34;&gt;#&lt;/a&gt;
&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;साइनअप, प्रदाता सेटिंग:&lt;/strong&gt; यदि व्यवस्थापक या पहचान प्रदाता खाते बनाता है, तो खुले साइनअप को बंद करें। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;हार्डनिंग गाइड&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/advanced-topics/hardening/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/advanced-topics/hardening/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;हार्डनिंग गाइड&lt;/a&gt;
&lt;/span&gt;
 के आधार पर &lt;code&gt;ENABLE_SIGNUP&lt;/code&gt; और स्थायी एडमिन सेटिंग जाँचें। नए खातों के लिए कड़े अनुमोदन नियम रखें।&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;API कुंजियाँ, ऑपरेटर समीक्षा:&lt;/strong&gt; जारी की गई कुंजियों की सूची बनाएँ, अनुपयोगी कुंजियाँ हटाएँ और निर्माण तथा एंडपॉइंट पहुँच को आवश्यक भूमिकाओं व मार्गों तक सीमित करें। प्रदाता की गाइड के अनुसार कुंजी अपने निर्माता की अनुमतियों से काम करती है। कुंजियाँ लेख के उदाहरणों और ऐप लॉग से बाहर रखें।&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;व्यवस्थापक, ऑपरेटर समीक्षा:&lt;/strong&gt; छोड़े गए एडमिन खाते हटाएँ, मजबूत लॉगिन नियंत्रण लागू करें, MFA उपलब्धता जाँचें और अनपेक्षित खाता बदलावों की जाँच करें। अतिरिक्त व्यवस्थापक को बंद करने से पहले खाता पुनर्प्राप्ति प्रक्रिया परखें।&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;नेटवर्क सीमा, प्रदाता मार्गदर्शन:&lt;/strong&gt; सेवा को VPN, एक्सेस प्रॉक्सी या प्रमाणीकरण और IP अनुमति-सूची वाले रिवर्स प्रॉक्सी के पीछे रखें। बिना प्रमाणीकरण इसे सार्वजनिक न करें। पहुँच योग्य सेवा पर &lt;code&gt;WEBUI_AUTH=False&lt;/code&gt; से बचें। अपने प्रमाणीकरण के बिना रिवर्स प्रॉक्सी ऐप में साइन-इन का विकल्प नहीं है। 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;Open WebUI को सुरक्षित करें&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://docs.openwebui.com/getting-started/advanced-topics/hardening/&#34;&gt;
    &lt;a href=&#34;https://docs.openwebui.com/getting-started/advanced-topics/hardening/&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;Open WebUI को सुरक्षित करें&lt;/a&gt;
&lt;/span&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;दायरा:&lt;/strong&gt; यह चेकलिस्ट आधिकारिक Open WebUI रिलीज़ और दस्तावेज़ित मानक इंस्टॉल विधियों पर लागू है। यह fork, व्युत्पन्न इमेज या तृतीय-पक्ष पैकेज की जाँच नहीं करती। v0.12.4 नोट सक्रिय शोषण का दावा नहीं करते। बाद के खुलासों और उनकी प्रभावित तथा ठीक की गई संस्करण सीमाओं के लिए 


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;प्रोजेक्ट सुरक्षा सलाह&#34;&gt;
    &lt;meta itemprop=&#34;url&#34; content=&#34;https://github.com/open-webui/open-webui/security/advisories&#34;&gt;
    &lt;a href=&#34;https://github.com/open-webui/open-webui/security/advisories&#34;




                    rel=&#34;noopener external&#34; target=&#34;_blank&#34;



    &gt;प्रोजेक्ट सुरक्षा सलाह&lt;/a&gt;
&lt;/span&gt;
 देखें। पहले की सलाह में दिए सुधार को v0.12.4 से न जोड़ें, जब तक उसका संस्करण दायरा न पढ़ लें।&lt;/p&gt;
&lt;h2 id=&#34;सरत-और-सदरभ&#34;&gt;
  &lt;a href=&#34;#%e0%a4%b8%e0%a4%b0%e0%a4%a4-%e0%a4%94%e0%a4%b0-%e0%a4%b8%e0%a4%a6%e0%a4%b0%e0%a4%ad&#34; title=&#34;स्रोत और संदर्भ&#34;&gt;स्रोत और संदर्भ&lt;/a&gt;
  &lt;a href=&#34;#%e0%a4%b8%e0%a4%b0%e0%a4%a4-%e0%a4%94%e0%a4%b0-%e0%a4%b8%e0%a4%a6%e0%a4%b0%e0%a4%ad&#34; class=&#34;h-anchor&#34; aria-hidden=&#34;true&#34; title=&#34;स्रोत और संदर्भ&#34;&gt;#&lt;/a&gt;
&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;


































































































































&lt;span itemscope itemtype=&#34;https://schema.org/WebPage&#34;&gt;
    &lt;meta itemprop=&#34;name&#34; content=&#34;Open WebUI v0.12.4 रिलीज़ नोट&#34;&gt;
